type Paths<T> = T extends object
  ? { [K in keyof T & string]: T[K] extends object ? K | `${K}.${Paths<T[K]>}` : K }[keyof T & string]
  : never;

function paths<T extends object>(obj: T): Paths<T>[] {
  const walk = (o: any): string[] => {
    const out: string[] = [];
    for (const k of Object.keys(o)) {
      out.push(k);
      const v = o[k];
      if (v !== null && typeof v === "object" && !Array.isArray(v)) {
        for (const sub of walk(v)) { out.push(k + "." + sub); }
      }
    }
    return out;
  };
  return walk(obj) as Paths<T>[];
}

