// 残り深さを 1 減らすための表。Prev[3] は 2、Prev[1] は 0
type Prev = [never, 0, 1, 2, 3, 4, 5];

type Paths<T, D extends number = 3> = D extends 0
  ? never
  : T extends object
    ? {
        [K in keyof T & string]: T[K] extends object
          ? K | `${K}.${Paths<T[K], Prev[D]>}`
          : K;
      }[keyof T & string]
    : never;

function collectPaths(value: unknown, maxDepth: number): string[] {
  if (maxDepth <= 0 || typeof value !== "object" || value === null || Array.isArray(value)) {
    return [];
  }
  const record = value as Record<string, unknown>;
  const out: string[] = [];
  for (const key of Object.keys(record)) {
    out.push(key);
    for (const sub of collectPaths(record[key], maxDepth - 1)) {
      out.push(key + "." + sub);
    }
  }
  return out;
}

