function mapValues<T extends Record<string, unknown>, R>(
  obj: T,
  fn: (value: T[keyof T], key: keyof T & string) => R,
): { [K in keyof T]: R } {
  const out = {} as { [K in keyof T]: R };
  for (const key of Object.keys(obj)) {
    out[key as keyof T] = fn(obj[key as keyof T] as T[keyof T], key as keyof T & string);
  }
  return out;
}

