type Unit<Name extends string> = { readonly __unit: Name };

type Meters = number & Unit<"m">;
type Seconds = number & Unit<"s">;
type MetersPerSecond = number & Unit<"m/s">;

function meters(value: number): Meters {
  return value as Meters;
}

function seconds(value: number): Seconds {
  return value as Seconds;
}

function speed(distance: Meters, time: Seconds): MetersPerSecond {
  if (time === 0) {
    throw new RangeError("時間が 0 では速度を定義できません");
  }
  return ((distance as number) / (time as number)) as MetersPerSecond;
}

