declare const emailBrand: unique symbol;
type Email = string & { readonly [emailBrand]: true };

function parseEmail(raw: string): Email | null {
  const parts = raw.split("@");
  if (parts.length !== 2) {
    return null;
  }
  const local = parts[0];
  const domain = parts[1];
  if (local.length === 0 || domain.length === 0 || domain.indexOf(".") < 0) {
    return null;
  }
  return raw as Email;
}

function sendTo(to: Email): string {
  return "sent:" + to;
}

