type RequestSpec = { url: string; method: string; body?: string };
type RequiredKeys = "url" | "method";

type RequestBuilder<Have extends keyof RequestSpec = never> = {
  url(value: string): RequestBuilder<Have | "url">;
  method(value: string): RequestBuilder<Have | "method">;
  body(value: string): RequestBuilder<Have | "body">;
} & ([Exclude<RequiredKeys, Have>] extends [never] ? { build(): RequestSpec } : {});

function request(): RequestBuilder {
  const make = (data: Partial<RequestSpec>): unknown => ({
    url: (value: string) => make({ ...data, url: value }),
    method: (value: string) => make({ ...data, method: value }),
    body: (value: string) => make({ ...data, body: value }),
    build: () => ({ ...data }),
  });
  return make({}) as RequestBuilder;
}

