answer_code:
type AppEvents = {
  message: { text: string };
  count: number;
};

class Emitter<E> {
  private listeners: { [K in keyof E]?: Array<(payload: E[K]) => void> } = {};

  on<K extends keyof E>(name: K, listener: (payload: E[K]) => void): void {
    const current = this.listeners[name] || [];
    current.push(listener);
    this.listeners[name] = current;
  }

  emit<K extends keyof E>(name: K, payload: E[K]): void {
    for (const listener of this.listeners[name] || []) {
      listener(payload);
    }
  }
}

