type Shape =
  | { kind: "circle"; r: number }
  | { kind: "square"; size: number }
  | { kind: "rect"; w: number; h: number };

type AreaHandlers = {
  [K in Shape["kind"]]: (shape: Extract<Shape, { kind: K }>) => number;
};

const areaHandlers: AreaHandlers = {
  circle: (shape) => Math.PI * shape.r * shape.r,
  square: (shape) => shape.size * shape.size,
  rect: (shape) => shape.w * shape.h,
};

function area(shape: Shape): number {
  const handler = areaHandlers[shape.kind] as (s: Shape) => number;
  return handler(shape);
}

