answer_code:
type Expr =
  | { kind: "lit"; value: number }
  | { kind: "neg"; expr: Expr }
  | { kind: "add"; left: Expr; right: Expr }
  | { kind: "mul"; left: Expr; right: Expr };

function evaluate(expr: Expr): number {
  switch (expr.kind) {
    case "lit":
      return expr.value;
    case "neg":
      return -evaluate(expr.expr);
    case "add":
      return evaluate(expr.left) + evaluate(expr.right);
    case "mul":
      return evaluate(expr.left) * evaluate(expr.right);
  }
}

