type Shape =
  | { kind: "circle"; r: number }
  | { kind: "square"; side: number }
  | { kind: "rect"; w: number; h: number };

function assertNever(x: never): never {
  throw new Error("unreachable: " + JSON.stringify(x));
}

function area(s: Shape): number {
  switch (s.kind) {
    case "circle":
      return Math.PI * s.r * s.r;
    case "square":
      return s.side * s.side;
    case "rect":
      return s.w * s.h;
    default:
      return assertNever(s);
  }
}

function widen<K extends Shape["kind"]>(
  kind: K,
  handler: (s: Extract<Shape, { kind: K }>) => number,
  fallback: number,
): (s: Shape) => number {
  return (s) => (s.kind === kind ? handler(s as Extract<Shape, { kind: K }>) : fallback);
}

description_md:
イベント名ごとにペイロードの形が違うイベントエミッタを、**名前とペイロードが型で結びつく** ように実装してください。`(e: any) => void` で受けてしまうと、ハンドラの中で何でも触れてしまい型検査が意味を失います。

```typescript
const em = new Emitter();
em.on("click", (e) => e.x + e.y);      // e は { x: number; y: number }
em.emit("click", { x: 1, y: 2 });
em.emit("keydown", { key: "a" });      // ペイロードの形は名前ごとに決まる
```

`on` / `off` / `emit` の 3 つを実装します。ハンドラが 1 つも登録されていない名前に `emit` しても例外にはなりません。`off` は同じ関数オブジェクトを渡したときだけ 1 件だけ取り除きます。

starter_code:
type EventMap = {
  click: { x: number; y: number };
  keydown: { key: string };
  reset: { reason: string };
};

