answer_code:
type EventMap = {
  click: { x: number; y: number };
  keydown: { key: string };
  reset: { reason: string };
};

class Emitter {
  private handlers = new Map<string, Array<(e: never) => void>>();

  on<K extends keyof EventMap>(type: K, handler: (e: EventMap[K]) => void): void {
    const key = String(type);
    const list = this.handlers.get(key);
    if (list === undefined) {
      this.handlers.set(key, [handler as (e: never) => void]);
    } else {
      list.push(handler as (e: never) => void);
    }
  }

  off<K extends keyof EventMap>(type: K, handler: (e: EventMap[K]) => void): void {
    const list = this.handlers.get(String(type));
    if (list === undefined) return;
    const i = list.indexOf(handler as (e: never) => void);
    if (i >= 0) list.splice(i, 1);
  }

  emit<K extends keyof EventMap>(type: K, payload: EventMap[K]): void {
    const list = this.handlers.get(String(type));
    if (list === undefined) return;
    for (const h of list.slice()) {
      (h as (e: EventMap[K]) => void)(payload);
    }
  }
}

