function countWords(words: string[]): Record<string, number> {
  const counts: Record<string, number> = Object.create(null) as Record<string, number>;
  for (const w of words) {
    counts[w] = (Object.prototype.hasOwnProperty.call(counts, w) ? counts[w] : 0) + 1;
  }
  return counts;
}

function lookup(counts: Record<string, number>, key: string): number | undefined {
  return Object.prototype.hasOwnProperty.call(counts, key) ? counts[key] : undefined;
}

