function at<T>(xs: readonly T[], i: number): T | undefined {
  if (!Number.isInteger(i)) return undefined;
  const idx = i < 0 ? xs.length + i : i;
  if (idx < 0 || idx >= xs.length) return undefined;
  return xs[idx];
}

function expectAt<T>(xs: readonly T[], i: number): T {
  const v = at(xs, i);
  if (v === undefined) {
    throw new RangeError("index " + i + " out of range (length " + xs.length + ")");
  }
  return v;
}

