class Widget {
  constructor(public name: string) {}

  render(): string {
    return "<" + this.name + ">";
  }

  renderArrow = (): string => "<" + this.name + ">";
}

function memberLocation(obj: object, key: string): "own" | "prototype" | "missing" {
  if (Object.prototype.hasOwnProperty.call(obj, key)) return "own";
  let p: object | null = Object.getPrototypeOf(obj);
  while (p !== null) {
    if (Object.prototype.hasOwnProperty.call(p, key)) return "prototype";
    p = Object.getPrototypeOf(p);
  }
  return "missing";
}

function sharesFunction(a: object, b: object, key: string): boolean {
  const va = (a as Record<string, unknown>)[key];
  const vb = (b as Record<string, unknown>)[key];
  return typeof va === "function" && va === vb;
}

