class Animal {
  speak(): string { return "..."; }
  describe(): string { return "I say " + this.speak(); }
}

class Dog extends Animal {
  speak(): string { return "wan"; }
  fetch(): string { return "ball"; }
}

class Puppy extends Dog {}

function protoName(p: object): string {
  const ctor = (p as { constructor?: { name?: string } }).constructor;
  return ctor !== undefined && typeof ctor.name === "string" && ctor.name !== "" ? ctor.name : "(anonymous)";
}

function prototypeChain(obj: object): string[] {
  const names: string[] = [];
  let p: object | null = Object.getPrototypeOf(obj);
  while (p !== null) {
    names.push(protoName(p));
    p = Object.getPrototypeOf(p);
  }
  return names;
}

function methodOwner(obj: object, key: string): string | null {
  let p: object | null = Object.getPrototypeOf(obj);
  while (p !== null) {
    if (Object.prototype.hasOwnProperty.call(p, key)) return protoName(p);
    p = Object.getPrototypeOf(p);
  }
  return null;
}

