answer_code:
type Wrapped<F extends (...args: any[]) => any> = (...args: Parameters<F>) => ReturnType<F>;

function withRetry<F extends (...args: any[]) => any>(fn: F, attempts: number): Wrapped<F> {
  const total = attempts < 1 ? 1 : attempts;
  return (...args: Parameters<F>): ReturnType<F> => {
    let last: unknown;
    for (let i = 0; i < total; i++) {
      try {
        return fn(...args) as ReturnType<F>;
      } catch (e) {
        last = e;
      }
    }
    throw last;
  };
}

