answer_code:
type Curried<A extends unknown[], R> = A extends [infer H, ...infer T]
  ? (T extends [] ? (h: H) => R : (h: H) => Curried<T, R>)
  : R;

function curry<A extends unknown[], R>(fn: (...args: A) => R): Curried<A, R> {
  const arity = fn.length;
  const collect = (acc: unknown[]): unknown => {
    if (acc.length >= arity) return fn(...(acc as A));
    return (x: unknown): unknown => collect(acc.concat([x]));
  };
  return (arity === 0 ? fn(...([] as unknown as A)) : collect([])) as Curried<A, R>;
}

