  if (Number.isNaN(a) && Number.isNaN(b)) return true;
  return a === b;
}

function indexOfValue(xs: readonly number[], target: number): number {
  for (let i = 0; i < xs.length; i++) {
    if (sameValueZero(xs[i], target)) return i;
  }
  return -1;
}

