function toBigIntExact(n: number): bigint | null {
  return Number.isInteger(n) ? BigInt(n) : null;
}

function addMixed(a: bigint, b: number): bigint | null {
  const nb = toBigIntExact(b);
  return nb === null ? null : a + nb;
}

function factorial(n: number): bigint | null {
  if (!Number.isInteger(n) || n < 0) return null;
  let acc = 1n;
  for (let i = 2n; i <= BigInt(n); i++) {
    acc *= i;
  }
  return acc;
}

