type Player = { name: string; score: number };
type Cmp<T> = (a: T, b: T) => number;

function byScoreThenName(a: Player, b: Player): number {
  if (a.score !== b.score) return b.score - a.score;
  if (a.name < b.name) return -1;
  if (a.name > b.name) return 1;
  return 0;
}

function isConsistent<T>(cmp: Cmp<T>, samples: readonly T[]): boolean {
  const sign = (n: number): number => (n > 0 ? 1 : n < 0 ? -1 : 0);
  const n = samples.length;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (sign(cmp(samples[i], samples[j])) !== -sign(cmp(samples[j], samples[i]))) return false;
    }
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (sign(cmp(samples[i], samples[j])) > 0) continue;
      for (let k = 0; k < n; k++) {
        if (sign(cmp(samples[j], samples[k])) > 0) continue;
        if (sign(cmp(samples[i], samples[k])) > 0) return false;
      }
    }
  }
  return true;
}

