type Rec = { name: string; dept: string; score: number };

function rankRecords(rows: Rec[]): Rec[] {
  const byScore = rows.slice().sort((a, b) => b.score - a.score);
  return byScore.sort((a, b) => (a.dept < b.dept ? -1 : a.dept > b.dept ? 1 : 0));
}

