type UserRec = { id: number; label: string };
type OrderRec = { userId: number; amount: number };
type SummaryRec = { id: number; label: string; total: number };

function summarize(users: UserRec[], orders: OrderRec[]): SummaryRec[] {
  const out: SummaryRec[] = users.map((u) => ({ id: u.id, label: u.label, total: 0 }));
  const index = new Map<number, SummaryRec>();
  for (const row of out) {
    index.set(row.id, row);
  }
  for (const o of orders) {
    const row = index.get(o.userId);
    if (row !== undefined) {
      row.total += o.amount;
    }
  }
  return out;
}

