answer_code:
function filterMap<T, U>(items: T[], transform: (value: T, index: number) => U | undefined): U[] {
  const out: U[] = [];
  for (let i = 0; i < items.length; i++) {
    const value = transform(items[i], i);
    if (value !== undefined) {
      out.push(value);
    }
  }
  return out;
}

