answer_code:
function setIn<T, K1 extends keyof T, K2 extends keyof T[K1]>(
  source: T,
  key1: K1,
  key2: K2,
  value: T[K1][K2]
): T {
  const inner: any = Object.assign({}, source[key1]);
  inner[key2] = value;
  const outer: any = Object.assign({}, source);
  outer[key1] = inner;
  return outer as T;
}

