type Section = { title: string; lines: string[] };

function replaceLine(doc: Section[], sectionIndex: number, lineIndex: number, text: string): Section[] {
  const nextLines = doc[sectionIndex].lines.slice();
  nextLines[lineIndex] = text;
  const nextSection: Section = { title: doc[sectionIndex].title, lines: nextLines };
  const out = doc.slice();
  out[sectionIndex] = nextSection;
  return out;
}

