answer_code:
function toReiterable<T>(source: Iterator<T>): Iterable<T> {
  const buffer: T[] = [];
  let exhausted = false;
  return {
    [Symbol.iterator](): Iterator<T> {
      let i = 0;
      return {
        next(): IteratorResult<T> {
          if (i < buffer.length) {
            return { value: buffer[i++], done: false };
          }
          if (exhausted) {
            return { value: undefined as any, done: true };
          }
          const step = source.next();
          if (step.done === true) {
            exhausted = true;
            return { value: undefined as any, done: true };
          }
          buffer.push(step.value);
          i++;
          return { value: step.value, done: false };
        },
      };
    },
  };
}

