answer_code:
function* naturals(start: number): Generator<number> {
  let n = start;
  while (true) {
    yield n;
    n++;
  }
}

function* mapG<T, U>(source: Iterable<T>, transform: (value: T) => U): Generator<U> {
  for (const value of source) {
    yield transform(value);
  }
}

function* filterG<T>(source: Iterable<T>, keep: (value: T) => boolean): Generator<T> {
  for (const value of source) {
    if (keep(value)) {
      yield value;
    }
  }
}

function takeG<T>(source: Iterable<T>, n: number): T[] {
  const out: T[] = [];
  if (n <= 0) {
    return out;
  }
  for (const value of source) {
    out.push(value);
    if (out.length >= n) {
      break;
    }
  }
  return out;
}

