type CancelSignal = { readonly cancelled: boolean };
type Canceller = { signal: CancelSignal; cancel: () => void };

function createCanceller(): Canceller {
  const state = { cancelled: false };
  return {
    signal: state,
    cancel: () => {
      state.cancelled = true;
    },
  };
}

async function repeatUntilCancelled(
  step: (round: number) => Promise<void>,
  signal: CancelSignal
): Promise<number> {
  let count = 0;
  while (!signal.cancelled) {
    await step(count);
    count++;
  }
  return count;
}

