type SettleReport<T> = { values: T[]; failures: { index: number; reason: string }[] };

async function settleAll<T>(tasks: Array<() => Promise<T>>): Promise<SettleReport<T>> {
  const settled = await Promise.allSettled(tasks.map(async (task) => task()));
  const values: T[] = [];
  const failures: { index: number; reason: string }[] = [];
  settled.forEach((outcome, index) => {
    if (outcome.status === "fulfilled") {
      values.push(outcome.value);
    } else {
      const reason = outcome.reason;
      failures.push({
        index: index,
        reason: reason instanceof Error ? reason.message : String(reason),
      });
    }
  });
  return { values: values, failures: failures };
}

