answer_code:
type RetryOptions = {
  retries: number;
  delayMs: (attempt: number) => number;
  retryable: (error: unknown) => boolean;
};

async function retry<T>(task: (attempt: number) => Promise<T>, options: RetryOptions): Promise<T> {
  let attempt = 1;
  while (true) {
    try {
      return await task(attempt);
    } catch (error) {
      if (!options.retryable(error) || attempt > options.retries) {
        throw error;
      }
      const wait = options.delayMs(attempt);
      await new Promise<void>((resolve) => {
        setTimeout(resolve, wait);
      });
      attempt++;
    }
  }
}

