answer_code:
type Config = { host: string; port: number };

type ConfigError =
  | { kind: "invalid_json"; detail: string }
  | { kind: "missing_field"; detail: string }
  | { kind: "wrong_type"; detail: string };

type ParseResult =
  | { ok: true; value: Config }
  | { ok: false; error: ConfigError };

function fail(kind: ConfigError["kind"], detail: string): ParseResult {
  return { ok: false, error: { kind, detail } as ConfigError };
}

function parseConfig(text: string): ParseResult {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (e) {
    // 例外を外へ漏らさないのはこの 1 箇所だけ。ここがエラー境界。
    return fail("invalid_json", e instanceof Error ? e.message : String(e));
  }
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return fail("invalid_json", "オブジェクトではありません");
  }
  const record = raw as Record<string, unknown>;
  if (!("host" in record)) return fail("missing_field", "host");
  if (typeof record.host !== "string") return fail("wrong_type", "host");
  if (!("port" in record)) return fail("missing_field", "port");
  if (typeof record.port !== "number") return fail("wrong_type", "port");
  return { ok: true, value: { host: record.host, port: record.port } };
}

