answer_code:
// 配列や関数は「マージする対象のオブジェクト」から外す
type IsPlain<T> = T extends readonly unknown[]
  ? false
  : T extends (...args: never[]) => unknown
    ? false
    : T extends object
      ? true
      : false;

type DeepMerge<A, B> = {
  [K in keyof A | keyof B]: K extends keyof B
    ? K extends keyof A
      ? IsPlain<A[K]> extends true
        ? IsPlain<B[K]> extends true
          ? DeepMerge<A[K], B[K]>
          : B[K]
        : B[K]
      : B[K]
    : K extends keyof A
      ? A[K]
      : never;
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function deepMerge<A extends object, B extends object>(a: A, b: B): DeepMerge<A, B> {
  const out: Record<string, unknown> = { ...(a as unknown as Record<string, unknown>) };
  const right = b as unknown as Record<string, unknown>;
  for (const key of Object.keys(right)) {
    const before = out[key];
    const after = right[key];
    out[key] = isPlainObject(before) && isPlainObject(after) ? deepMerge(before, after) : after;
  }
  return out as unknown as DeepMerge<A, B>;
}

