answer_code:
type Invert<T extends Record<string, string>> = { [K in keyof T as T[K]]: K };

function invert<T extends Record<string, string>>(obj: T): Invert<T> {
  const source = obj as unknown as Record<string, string>;
  const out: Record<string, string> = {};
  for (const key of Object.keys(source)) {
    out[source[key]] = key;
  }
  return out as unknown as Invert<T>;
}

