answer_code:
type FormatOptions = {
  decimals?: number;
  separator?: string;
  currency?: string;
  sign?: boolean;
};

function formatAmount(amount: number, options: FormatOptions = {}): string {
  const { decimals = 0, separator = ",", currency = "", sign = false } = options;

  const fixed = Math.abs(amount).toFixed(decimals);
  const dot = fixed.indexOf(".");
  const intPart = dot < 0 ? fixed : fixed.slice(0, dot);
  const fracPart = dot < 0 ? "" : fixed.slice(dot);

  let grouped = "";
  for (let i = 0; i < intPart.length; i++) {
    const fromRight = intPart.length - i;
    if (i > 0 && fromRight % 3 === 0) grouped += separator;
    grouped += intPart.charAt(i);
  }

  const prefix = amount < 0 ? "-" : sign && amount > 0 ? "+" : "";
  return prefix + currency + grouped + fracPart;
}

