answer_code:
interface Clock {
  now(): number;
}

type RateLimiter<C extends Clock> = {
  clock: C;
  allow(key: string): boolean;
};

function createRateLimiter<C extends Clock>(clock: C, limit: number, windowMs: number): RateLimiter<C> {
  const hits = new Map<string, number[]>();
  return {
    clock,
    allow(key: string): boolean {
      const now = clock.now();
      const recent = (hits.get(key) || []).filter((t) => now - t < windowMs);
      if (recent.length >= limit) {
        hits.set(key, recent);
        return false;
      }
      recent.push(now);
      hits.set(key, recent);
      return true;
    },
  };
}

