type Either<L, R> = { tag: "left"; value: L } | { tag: "right"; value: R };

function left<L>(value: L): Either<L, never> {
  return { tag: "left", value };
}

function right<R>(value: R): Either<never, R> {
  return { tag: "right", value };
}

function mapRight<L, R, R2>(e: Either<L, R>, f: (value: R) => R2): Either<L, R2> {
  return e.tag === "right" ? { tag: "right", value: f(e.value) } : e;
}

function mapLeft<L, R, L2>(e: Either<L, R>, f: (value: L) => L2): Either<L2, R> {
  return e.tag === "left" ? { tag: "left", value: f(e.value) } : e;
}

function fold<L, R, T>(e: Either<L, R>, onLeft: (value: L) => T, onRight: (value: R) => T): T {
  return e.tag === "left" ? onLeft(e.value) : onRight(e.value);
}

