type Where<T> = {
  [K in keyof T]?: T[K] | { in: readonly T[K][] };
};

function isInCondition(value: unknown): value is { in: readonly unknown[] } {
  return typeof value === "object" && value !== null && Array.isArray((value as { in?: unknown }).in);
}

function matches<T>(row: T, where: Where<T>): boolean {
  const source = row as unknown as Record<string, unknown>;
  const conditions = where as unknown as Record<string, unknown>;
  for (const key of Object.keys(conditions)) {
    const condition = conditions[key];
    const value = source[key];
    if (isInCondition(condition)) {
      if (condition.in.indexOf(value) < 0) return false;
    } else if (condition !== value) {
      return false;
    }
  }
  return true;
}

