answer_code:
// ":" の直後から次の "/" まで、あるいは文字列の末尾までがパラメータ名
type ParamNames<P extends string> = P extends `${infer _Head}:${infer Tail}`
  ? Tail extends `${infer Name}/${infer Rest}`
    ? Name | ParamNames<Rest>
    : Tail
  : never;

type PathParams<P extends string> = { [K in ParamNames<P>]: string };

function buildPath<P extends string>(pattern: P, params: PathParams<P>): string {
  const table = params as unknown as Record<string, string>;
  return pattern
    .split("/")
    .map((segment) => {
      if (segment.charAt(0) !== ":") return segment;
      const name = segment.slice(1);
      const value = table[name];
      if (typeof value !== "string") {
        throw new Error("パラメータが足りません: " + name);
      }
      return encodeURIComponent(value);
    })
    .join("/");
}

