  ? [PlaceholderType<Kind>, ...FormatArgs<Rest>]
  : [];

function format<S extends string>(template: S, ...args: FormatArgs<S>): string {
  const values = args as unknown as ReadonlyArray<string | number>;
  let index = 0;
  return template.replace(/\{[ns]\}/g, () => String(values[index++]));
}

