answer_code:
// infer に constraint を付けると、TypeScript が文字列を数値リテラル型として解釈してくれる
type ToNumber<S extends string> = S extends `${infer N extends number}` ? N : never;

function toIndex(key: string): number {
  if (!/^\d+$/.test(key)) return -1;
  return Number(key);
}

