answer_code:
// Acc に積みながら進むので、条件型の「真の枝」がそのまま再帰呼び出しになる (末尾再帰)
type Split<S extends string, D extends string, Acc extends string[] = []> =
  S extends `${infer Head}${D}${infer Rest}`
    ? Split<Rest, D, [...Acc, Head]>
    : [...Acc, S];

function splitAll<S extends string, D extends string>(text: S, delimiter: D): Split<S, D> {
  return text.split(delimiter) as unknown as Split<S, D>;
}

description_md:
`"select <列>, <列> from <表>"` という小さなクエリ言語を解釈する `select` を作ります。**型レベルで列名を解析し、戻り値の型に反映** させるのが目的です。

```typescript
type Row = { name: string; age: number; city: string };
const rows: Row[] = [{ name: "ann", age: 30, city: "kyoto" }];

const out = select(rows, "select name, age from users");
// 値 => [{ name: "ann", age: 30 }]
// 型 => Array<Pick<Row, "name" | "age">>   ← city は型にも値にも無い
```

- `SelectedFields<Q>` — クエリ文字列から列名の **ユニオン型** を取り出す型。列名の前後の空白は取り除く
- `select(rows, query)` — 各行から選ばれた列だけを取り出した新しい配列を返す
- `select` の戻り値型は `Array<Pick<Row, Extract<SelectedFields<Q>, keyof Row>>>`
- クエリが `select ... from ...` の形でなければ `SyntaxError` を投げる

型レベルの解析と実行時の解析が **同じ結果になる** ことがこの問題の要求です。

