answer_code:
type Trim<S extends string> = S extends ` ${infer Rest}`
  ? Trim<Rest>
  : S extends `${infer Rest} `
    ? Trim<Rest>
    : S;

type FieldNames<C extends string> = C extends `${infer Head},${infer Rest}`
  ? Trim<Head> | FieldNames<Rest>
  : Trim<C>;

type SelectedFields<Q extends string> = Q extends `select ${infer Columns} from ${string}`
  ? FieldNames<Columns>
  : never;

function select<Row, Q extends string>(
  rows: readonly Row[],
  query: Q
): Array<Pick<Row, Extract<SelectedFields<Q>, keyof Row>>> {
  const parsed = /^select\s+(.+?)\s+from\s+(\S+)\s*$/.exec(query);
  if (parsed === null) {
    throw new SyntaxError("解釈できないクエリです: " + query);
  }
  const fields = parsed[1].split(",").map((name) => name.trim());
  const projected = rows.map((row) => {
    const source = row as unknown as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const field of fields) out[field] = source[field];
    return out;
  });
  return projected as unknown as Array<Pick<Row, Extract<SelectedFields<Q>, keyof Row>>>;
}
